mapper.select:
SELECT * FROM ai_episodic_memory
WHERE user_id = #{userId}
ORDER BY updated_at DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM ai_episodic_memory
WHERE user_id = #{userId}
  AND id NOT IN (
      SELECT id FROM (
          SELECT id FROM ai_episodic_memory
          WHERE user_id = #{userId}
          ORDER BY updated_at DESC
          LIMIT #{keepCount}
      ) t
  )

mapper.update:
UPDATE ai_episodic_memory
SET summary = #{summary}, updated_at = NOW()

    , topic = #{topic}


    , last_summarized_msg_count = #{lastSummarizedMsgCount}

WHERE session_id = #{sessionId}

mapper.select:
SELECT * FROM ai_episodic_memory
WHERE user_id = #{userId}
  AND updated_at >= DATE_SUB(NOW(), INTERVAL #{withinDays} DAY)
ORDER BY updated_at DESC
LIMIT #{limit}

SELECT * FROM ai_episodic_memory
WHERE user_id = #{userId}
  AND session_id <> #{excludeSessionId}
  AND updated_at >= DATE_SUB(NOW(), INTERVAL #{withinDays} DAY)
ORDER BY updated_at DESC
LIMIT #{limit}
